<script>(function(){var c=document.getElementById('canvas'),x=c.getContext('2d'),W,H,D=1,cs=5,cols,rows,g=[],mat='grain',brush=7,flow=.62,auto=true,down=false,tc=0;var hm=document.getElementById('h-mode'),hc=document.getElementById('h-cells'),hb=document.getElementById('h-brush'),hf=document.getElementById('h-flow'),sb=document.getElementById('sl-brush'),sf=document.getElementById('sl-flow'),vb=document.getElementById('sv-brush'),vf=document.getElementById('sv-flow'),ba=document.getElementById('btn-auto');function id(a,b){return b*cols+a}function at(a,b){return a<0||b<0||a>=cols||b>=rows?3:g[id(a,b)]}function set(a,b,v){if(a>=0&&b>=0&&a<cols&&b<rows)g[id(a,b)]=v}function resize(){D=Math.min(2,devicePixelRatio||1);W=c.width=Math.floor(innerWidth*D);H=c.height=Math.floor(innerHeight*D);c.style.width=innerWidth+'px';c.style.height=innerHeight+'px';cs=innerWidth<760?7:5;cols=Math.floor(W/cs);rows=Math.floor(H/cs);g=new Uint8Array(cols*rows)}function pour(px,py){var gx=Math.floor(px*D/cs),gy=Math.floor(py*D/cs),v=mat==='grain'?1:mat==='fluid'?2:mat==='wall'?3:0;for(var y=-brush;y<=brush;y++)for(var xx=-brush;xx<=brush;xx++){if(xx*xx+y*y<=brush*brush&&Math.random()<.72)set(gx+xx,gy+y,v)}tc++;hc.textContent=tc;if(typeof SFX!=='undefined')SFX.play(mat==='void'?'pop':'spawn',120)}function step(){if(auto&&Math.random()<.65)pour((.25+Math.random()*.5)*innerWidth,20+Math.random()*30);for(var y=rows-2;y>1;y--)for(var a=1;a<cols-1;a++){var i=id(a,y),v=g[i];if(v===1){var dir=Math.random()<.5?-1:1;if(at(a,y+1)===0){set(a,y+1,1);set(a,y,0)}else if(at(a+dir,y+1)===0){set(a+dir,y+1,1);set(a,y,0)}else if(at(a-dir,y+1)===0){set(a-dir,y+1,1);set(a,y,0)}}else if(v===2){var d=Math.random()<.5?-1:1;if(at(a,y+1)===0){set(a,y+1,2);set(a,y,0)}else if(Math.random()<flow&&at(a+d,y)===0){set(a+d,y,2);set(a,y,0)}else if(at(a-d,y)===0){set(a-d,y,2);set(a,y,0)}}}}function draw(){for(var k=0;k<2;k++)step();x.fillStyle='#0a0a0f';x.fillRect(0,0,W,H);for(var y=0;y<rows;y++)for(var a=0;a<cols;a++){var v=g[id(a,y)];if(!v)continue;x.fillStyle=v===1?'rgba(0,245,212,.78)':v===2?'rgba(123,44,191,.72)':'rgba(78,92,112,.72)';x.fillRect(a*cs,y*cs,cs,cs)}requestAnimationFrame(draw)}function hud(){hm.textContent=mat.toUpperCase();hb.textContent=brush;vb.textContent=brush;hf.textContent=flow.toFixed(2);vf.textContent=flow.toFixed(2)}c.addEventListener('pointerdown',e=>{down=true;pour(e.clientX,e.clientY)});c.addEventListener('pointermove',e=>{if(down||e.buttons)pour(e.clientX,e.clientY)});addEventListener('pointerup',()=>down=false);document.querySelectorAll('[data-mat]').forEach(b=>b.onclick=()=>{mat=b.dataset.mat;document.querySelectorAll('[data-mat]').forEach(q=>q.classList.toggle('active',q===b));hud();if(typeof SFX!=='undefined')SFX.play('toggle')});sb.oninput=()=>{brush=+sb.value;hud()};sf.oninput=()=>{flow=+sf.value/100;hud()};ba.onclick=()=>{auto=!auto;ba.classList.toggle('active',auto);if(typeof SFX!=='undefined')SFX.play('toggle')};document.getElementById('btn-clear').onclick=()=>{g.fill(0);tc=0;hc.textContent=0;if(typeof SFX!=='undefined')SFX.play('success')};addEventListener('resize',resize);resize();hud();draw()})();</script><?php require_once __DIR__ . '/includes/sfx.php';require_once __DIR__ . '/includes/page-end.php';?></body></html>